$propertyId=manage_active_property_id();$property=$propertyId?manage_property($propertyId):null;$years=range(2026,2045);$systemNow=new DateTimeImmutable('now',new DateTimeZone('America/Chicago'));$defaultPeriod=$systemNow->modify('first day of previous month');$year=(int)($_GET['year']??$defaultPeriod->format('Y'));$month=(int)($_GET['month']??$defaultPeriod->format('n'));
if(!in_array($year,$years,true))$year=2026;if($month<1||$month>12||($year===2026&&$month<7))$month=7;
$months=[1=>'January','February','March','April','May','June','July','August','September','October','November','December'];$monthProgress=[];$period=null;$transactions=[];$payments=[];$categoryTotals=[];$analysisRuns=[];$statementAnalysisCounts=[];$breakdownTotal=0.0;$filesByCategory=['statement'=>[],'payment'=>[]];$backupFilesByGroup=['manager'=>[],'owner'=>[],'owner_ach_check'=>[],'unassigned'=>[]];$selectedRunId=0;
if($property&&manage_receipts_schema_ready()){
 $q=db()->prepare('SELECT p.report_month,COUNT(t.id) item_count,COALESCE(SUM(CASE WHEN t.id IS NOT NULL AND (t.category_id IS NULL OR t.receipt_found=0) THEN 1 ELSE 0 END),0) incomplete_count FROM management_receipt_periods p LEFT JOIN management_receipt_transactions t ON t.management_receipt_period_id=p.id LEFT JOIN management_receipt_analysis_runs r ON r.id=t.analysis_run_id WHERE p.management_property_id=? AND p.report_year=? AND (t.id IS NULL OR r.is_current=1 OR t.analysis_run_id IS NULL) GROUP BY p.id,p.report_month');$q->execute([$propertyId,$year]);foreach($q->fetchAll() as $row)$monthProgress[(int)$row['report_month']]=['items'=>(int)$row['item_count'],'uncategorized'=>(int)$row['incomplete_count']];
 $q=db()->prepare('SELECT * FROM management_receipt_periods WHERE management_property_id=? AND report_year=? AND report_month=?');$q->execute([$propertyId,$year,$month]);$period=$q->fetch()?:null;
 if($period){$q=db()->prepare('SELECT * FROM management_receipt_files WHERE management_receipt_period_id=? ORDER BY id');$q->execute([(int)$period['id']]);foreach($q->fetchAll() as $file){if((string)$file['file_category']==='backup_invoices'){$group=(string)($file['receipt_group']??'unassigned');$backupFilesByGroup[isset($backupFilesByGroup[$group])?$group:'unassigned'][]=$file;}elseif(isset($filesByCategory[(string)$file['file_category']]))$filesByCategory[(string)$file['file_category']][]=$file;}$q=db()->prepare('SELECT r.*,f.original_name statement_name FROM management_receipt_analysis_runs r JOIN management_receipt_files f ON f.id=r.statement_file_id WHERE r.management_receipt_period_id=? ORDER BY r.created_at DESC,r.id DESC');$q->execute([(int)$period['id']]);$analysisRuns=$q->fetchAll();foreach($analysisRuns as $run)$statementAnalysisCounts[(int)$run['statement_file_id']]=($statementAnalysisCounts[(int)$run['statement_file_id']]??0)+1;$q=db()->prepare('SELECT statement_file_id,COUNT(*) item_count FROM management_receipt_transactions WHERE management_receipt_period_id=? GROUP BY statement_file_id');$q->execute([(int)$period['id']]);foreach($q->fetchAll() as $countRow)if((int)$countRow['item_count']>0)$statementAnalysisCounts[(int)$countRow['statement_file_id']]=max(1,$statementAnalysisCounts[(int)$countRow['statement_file_id']]??0);if($selectedRunId>0){$q=db()->prepare('SELECT t.*,f.original_name statement_name,c.category_name FROM management_receipt_transactions t JOIN management_receipt_files f ON f.id=t.statement_file_id LEFT JOIN management_receipt_categories c ON c.id=t.category_id WHERE t.management_receipt_period_id=? AND t.analysis_run_id=? ORDER BY t.card_last_four,t.transaction_date,t.id');$q->execute([(int)$period['id'],$selectedRunId]);}else{$q=db()->prepare('SELECT t.*,f.original_name statement_name,c.category_name FROM management_receipt_transactions t JOIN management_receipt_files f ON f.id=t.statement_file_id LEFT JOIN management_receipt_categories c ON c.id=t.category_id LEFT JOIN management_receipt_analysis_runs r ON r.id=t.analysis_run_id WHERE t.management_receipt_period_id=? AND (r.is_current=1 OR t.analysis_run_id IS NULL) ORDER BY t.card_last_four,t.transaction_date,t.id');$q->execute([(int)$period['id']]);}$transactions=$q->fetchAll();foreach($transactions as $transaction)$breakdownTotal+=(float)$transaction['amount'];if(manage_receipt_payments_schema_ready()){$q=db()->prepare('SELECT * FROM management_receipt_payments WHERE management_receipt_period_id=? ORDER BY payment_date,id');$q->execute([(int)$period['id']]);$payments=$q->fetchAll();}}
}
$receiptCategories=manage_receipts_schema_ready()?db()->query('SELECT id,category_name FROM management_receipt_categories WHERE is_active=1 ORDER BY category_name')->fetchAll():[];
$categoryTotals=array_fill_keys(array_column($receiptCategories,'category_name'),0.0);$categoryTotals['UNCATEGORIZED']=0.0;foreach($transactions as $transaction){$categoryName=trim((string)($transaction['category_name']??''))?:'UNCATEGORIZED';$categoryTotals[$categoryName]=($categoryTotals[$categoryName]??0)+(float)$transaction['amount'];}ksort($categoryTotals,SORT_NATURAL|SORT_FLAG_CASE);
$paymentTotal=array_sum(array_map(static fn(array $payment):float=>(float)$payment['amount_paid'],$payments));$paymentRemaining=$breakdownTotal-$paymentTotal;
$cpaDeliveries=[];if(manage_cpa_delivery_schema_ready()&&$propertyId>0){$q=db()->prepare('SELECT d.*,au.full_name sent_by_name FROM management_cpa_deliveries d LEFT JOIN admin_users au ON au.id=d.sent_by_admin_user_id WHERE d.management_property_id=? AND d.report_year=? AND d.report_month=? ORDER BY d.sent_at DESC,d.id DESC');$q->execute([$propertyId,$year,$month]);$cpaDeliveries=$q->fetchAll();}$receiptBreakdownLocked=!manage_is_admin()&&!empty($cpaDeliveries);
$transactionsByCard=[];foreach($transactions as $transaction){$lastFour=trim((string)($transaction['card_last_four']??''));$cardKey=$lastFour!==''?$lastFour:'unknown';if(!isset($transactionsByCard[$cardKey]))$transactionsByCard[$cardKey]=['label'=>trim((string)($transaction['cardholder']??'').($lastFour!==''?' #'.$lastFour:''))?:'Unknown Card','items'=>[],'subtotal'=>0.0,'charges'=>0.0,'payments'=>0.0,'uncategorized'=>0,'missing_receipts'=>0];$transactionsByCard[$cardKey]['items'][]=$transaction;if(empty($transaction['category_id']))$transactionsByCard[$cardKey]['uncategorized']++;if(empty($transaction['receipt_found']))$transactionsByCard[$cardKey]['missing_receipts']++;$amount=(float)$transaction['amount'];$transactionsByCard[$cardKey]['subtotal']+=$amount;if(($transaction['transaction_type']??'charge')==='charge')$transactionsByCard[$cardKey]['charges']+=$amount;else $transactionsByCard[$cardKey]['payments']+=$amount;}foreach($transactionsByCard as &$card){usort($card['items'],static function(array $a,array $b):int{$aPriority=($a['transaction_type']??'charge')==='charge'?1:0;$bPriority=($b['transaction_type']??'charge')==='charge'?1:0;return $aPriority<=>$bPriority?:strcmp((string)$a['transaction_date'],(string)$b['transaction_date'])?:((int)$a['id']<=>(int)$b['id']);});}unset($card);ksort($transactionsByCard,SORT_NATURAL);
