">Expand</span></span></summary><div class="manage-breakdown-table-wrap"><table class="manage-breakdown-table"><thead><tr><th>Date</th><th>Type</th><th>Description</th><th>Amount</th><th>Category</th><th>Receipt Found</th><th>Notes</th></tr></thead><tbody><?php foreach($card['items'] as $transaction):?><tr data-transaction-id="<?=(int)$transaction['id']?>"><td><?=manage_e(date('M j, Y',strtotime((string)$transaction['transaction_date'])))?></td><td><span class="manage-transaction-type <?=manage_e($transaction['transaction_type']??'charge')?>"><?=manage_e(ucfirst($transaction['transaction_type']??'charge'))?></span></td><td><?=manage_e($transaction['description'])?></td><td class="manage-breakdown-amount<?=((float)$transaction['amount']<0)?' credit':''?>">$<?=number_format((float)$transaction['amount'],2)?></td><td><select data-transaction-category <?=$receiptBreakdownLocked?'disabled':''?>><option value="">Uncategorized</option><?php foreach($receiptCategories as $category):?><option value="<?=(int)$category['id']?>" <?=((int)($transaction['category_id']??0)===(int)$category['id'])?'selected':''?>><?=manage_e($category['category_name'])?></option><?php endforeach;?></select></td><td><label class="manage-receipt-found-check"><input type="checkbox" data-receipt-found <?=!empty($transaction['receipt_found'])?'checked':''?> <?=$receiptBreakdownLocked?'disabled':''?>><span>Found</span></label></td><td><textarea data-transaction-notes rows="2" <?=$receiptBreakdownLocked?'disabled':''?> placeholder="Add notes"><?=manage_e($transaction['notes']??'')?></textarea><?php if(manage_is_admin()):?><button type="button" class="manage-transaction-delete" data-transaction-delete><i class="fa-solid fa-trash" aria-hidden="true"></i> Remove Item</button><?php endif;?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="3">Card Subtotal</th><th class="manage-breakdown-amount">$<?=number_format($card['subtotal'],2)?></th><th colspan="3"></th></tr></tfoot></table></div></details><?